/* map */
let mapView="kr";
function drawMap(){const svg=$("map");const [KW,KH]=MAPS.kv;
  if(mapView==="kr"){svg.setAttribute("viewBox",`0 0 ${KW} ${KH}`);
    let g="";for(let lat=33;lat<=38;lat++){const y=(MAPS.kv[3]-lat)*MAPS.kv[4];g+=`<line class="grid" x1="0" x2="${KW}" y1="${y}" y2="${y}"/>`}
    for(let lon=125;lon<=131;lon++){const x=(lon-MAPS.kv[2])*MAPS.kv[4]*MAPS.kv[5];g+=`<line class="grid" y1="0" y2="${KH}" x1="${x}" x2="${x}"/>`}
    svg.innerHTML=`<rect class="sea" width="${KW}" height="${KH}"/>${g}`+MAPS.nb.map(n=>`<path class="nb" data-c="${n[0]}" d="${n[1]}"/>`).join("")+MAPS.kor.map((r,i)=>`<path class="rg" data-i="${i}" d="${r[2]}"/>`).join("")+`<g id="mk"></g>`}
  else{const [WW,WH]=MAPS.wv;svg.setAttribute("viewBox",`0 0 ${WW} ${WH}`);
    svg.innerHTML=`<rect class="sea" width="${WW}" height="${WH}"/>`+MAPS.world.map((r,i)=>`<path class="rg" data-w="${i}" d="${r[2]}"/>`).join("")+`<g id="mk"></g>`}
  document.querySelectorAll(".maptabs button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.v===mapView));drawMarker()}
function proj(lat,lon){if(mapView==="kr")return [(lon-MAPS.kv[2])*MAPS.kv[4]*MAPS.kv[5],(MAPS.kv[3]-lat)*MAPS.kv[4]];return [(lon+180)*2.2,(84-lat)*2.2]}
function unproj(x,y){if(mapView==="kr")return [MAPS.kv[3]-y/MAPS.kv[4],MAPS.kv[2]+x/(MAPS.kv[4]*MAPS.kv[5])];return [84-y/2.2,x/2.2-180]}
function drawMarker(){const g=document.getElementById("mk");if(!g)return;if(place.unset){g.innerHTML="";return}const [x,y]=proj(place.lat,place.lon);const r=mapView==="kr"?4:3;
  g.innerHTML=`<circle class="mkr" cx="${x}" cy="${y}" r="${r*2}"/><circle class="mk" cx="${x}" cy="${y}" r="${r}"/>`}
function svgPt(e){const svg=$("map"),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}
function hitName(t){if(t.dataset.i!=null){const r=MAPS.kor[+t.dataset.i];return {name:(r[1]?r[1]+" ":"")+r[0],kr:true,iso:"KOR"}}
  if(t.dataset.c){return {name:KNAME[t.dataset.c]||t.dataset.c,kr:false,iso:t.dataset.c}}
  if(t.dataset.w!=null){const r=MAPS.world[+t.dataset.w];return {name:KNAME[r[0]]||r[1],kr:r[0]==="KOR",iso:r[0]}}return null}
$("map").addEventListener("pointermove",e=>{const h=hitName(e.target);const tip=$("mapTip");if(!h){tip.hidden=true;return}
  const wr=$("map").parentElement.getBoundingClientRect();tip.style.left=(e.clientX-wr.left)+"px";tip.style.top=(e.clientY-wr.top)+"px";tip.textContent=h.name;tip.hidden=false});
$("map").addEventListener("pointerleave",()=>{$("mapTip").hidden=true});
$("map").addEventListener("click",e=>{const h=hitName(e.target);if(!h){$("mapHint").textContent="육지를 눌러 주세요";return}
  if(mapView==="w"&&h.iso==="KOR"){mapView="kr";drawMap();$("mapHint").textContent="대한민국 지도로 바꿨어요. 시·군·구를 눌러 주세요";return}
  const pt=svgPt(e);const [lat,lon]=unproj(pt.x,pt.y);
  const tz=h.kr?9:(TZC[h.iso]!=null?TZC[h.iso]:Math.round(lon/15));
  place={name:h.name,lat:+lat.toFixed(3),lon:+lon.toFixed(3),tz,kr:h.kr};if(e.target.dataset.i!=null)place.ki=+e.target.dataset.i;else if(e.target.dataset.w!=null)place.wi=+e.target.dataset.w;syncSel();
  document.querySelectorAll("#map .rg.on").forEach(p=>p.classList.remove("on"));if(e.target.classList.contains("rg"))e.target.classList.add("on");
  showPlace();drawMarker();$("mapHint").textContent=h.kr?"선택했어요":"선택했어요. 시간대(UTC)가 맞는지 확인해 주세요"});
document.querySelectorAll(".maptabs button").forEach(b=>b.addEventListener("click",()=>{mapView=b.dataset.v;drawMap()}));
$("quick").innerHTML=[0,1,3,2,5,4,25,9,26,28,32,33,34].map(i=>`<button type="button" data-q="${i}">${PLACES[i][0]}</button>`).join("");
$("quick").addEventListener("click",e=>{const q=e.target.dataset.q;if(q==null)return;place=placeFromIdx(+q);if(place.kr&&PLACES[q][0].length<=3)place.name=PLACES[q][0];showPlace();mapView=place.kr?"kr":"w";drawMap()});
$("in-tz").addEventListener("change",e=>{const v=parseFloat(e.target.value);if(!isNaN(v)){place.tz=v;place.kr=false;showPlace()}});
function toggleMap(open){$("mapbox").hidden=!open;$("mapBtn").setAttribute("aria-expanded",open);$("mapBtn").textContent=open?"지도 닫기":"지도로 보기";if(open){mapView=place.kr||!("lat" in place)?"kr":"w";drawMap()}}
$("mapBtn").addEventListener("click",()=>toggleMap($("mapbox").hidden));$("mapDone").addEventListener("click",()=>toggleMap(false));
/* ---------- 출생지 고르기: 검색 + 시·도/시·군·구 선택 + (선택) 지도 ---------- */
const kname=n=>n.replace(/^(.+?시)(.+[구군])$/,"$1 $2");

const KC=MAPS_KC,WC=MAPS_WC;
const SIDO=[...new Set(MAPS.kor.map(r=>r[1]))].sort((a,b)=>a.localeCompare(b,"ko"));
const ABROAD=PLACES.map((p,i)=>[p,i]).filter(([p])=>!(p[3]===9&&p[2]>124&&p[2]<132&&p[1]>33&&p[1]<39));
const WORLD=MAPS.world.map((r,i)=>[KNAME[r[0]]||r[1],i]).filter(([,i])=>MAPS.world[i][0]!=="KOR").sort((a,b)=>a[0].localeCompare(b[0],"ko"));
const norm2=t=>t.replace(/\s+/g,"").toLowerCase();
const PIDX=[...MAPS.kor.map((r,i)=>({k:"kr",i,label:kname(r[0]),sub:r[1],key:norm2(r[1]+r[0])})),
  ...ABROAD.map(([p,i])=>({k:"city",i,label:p[0],sub:"해외 도시",key:norm2(p[0])})),
  ...WORLD.map(([n,i])=>({k:"w",i,label:n,sub:"나라 · "+MAPS.world[i][1],key:norm2(n+MAPS.world[i][1])}))];
function choosePlace(o){if(o.k==="kr"){const r=MAPS.kor[o.i];place={name:`${r[1]} ${kname(r[0])}`,lat:+KC[o.i][0].toFixed(3),lon:+KC[o.i][1].toFixed(3),tz:9,kr:true,ki:o.i}}
  else if(o.k==="city"){const p=PLACES[o.i];place={name:p[0],lat:p[1],lon:p[2],tz:p[3],kr:false,ci:o.i}}
  else{const r=MAPS.world[o.i];const [la,lo]=WC[o.i];place={name:KNAME[r[0]]||r[1],lat:+la.toFixed(2),lon:+lo.toFixed(2),tz:TZC[r[0]]!=null?TZC[r[0]]:Math.round(lo/15),kr:false,wi:o.i}}
  showPlace();syncSel();if(!$("mapbox").hidden){mapView=place.kr?"kr":"w";drawMap()}}
function fillSido(){$("sido").innerHTML=`<option value="">시·도</option>`+SIDO.map(n=>`<option>${n}</option>`).join("")+`<option value="abroad">해외</option>`}
function fillSgg(sd,keep){const el=$("sgg");if(!sd){el.innerHTML=`<option value="">시·군·구</option>`;el.disabled=true;return}el.disabled=false;
  if(sd==="abroad"){el.innerHTML=`<option value="">나라·도시 선택</option><optgroup label="주요 도시">${ABROAD.map(([p,i])=>`<option value="city:${i}">${p[0]}</option>`).join("")}</optgroup><optgroup label="나라">${WORLD.map(([n,i])=>`<option value="w:${i}">${n}</option>`).join("")}</optgroup>`}
  else el.innerHTML=`<option value="">시·군·구 선택</option>`+MAPS.kor.map((r,i)=>[r,i]).filter(([r])=>r[1]===sd).sort((a,b)=>a[0][0].localeCompare(b[0][0],"ko")).map(([r,i])=>`<option value="kr:${i}">${kname(r[0])}</option>`).join("");
  if(keep)el.value=keep}
function syncSel(){if(place.unset){$("sido").value="";fillSgg("");return}if(place.ki!=null){const sd=MAPS.kor[place.ki][1];$("sido").value=sd;fillSgg(sd,"kr:"+place.ki)}else if(place.sidoOnly){$("sido").value=place.name;fillSgg(place.name)}
  else if(place.ci!=null){$("sido").value="abroad";fillSgg("abroad","city:"+place.ci)}else if(place.wi!=null){$("sido").value="abroad";fillSgg("abroad","w:"+place.wi)}
  else if(place.kr){const sd=SIDO.find(n=>place.name.startsWith(n));$("sido").value=sd||"";fillSgg(sd||"")}}
$("sido").addEventListener("change",e=>{const sd=e.target.value;fillSgg(sd);if(!sd||sd==="abroad")return;const places=MAPS.kor.map((r,i)=>[r,i]).filter(([r])=>r[1]===sd);if(!places.length)return;const coords=places.map(([,i])=>KC[i]);const lat=coords.reduce((a,p)=>a+p[0],0)/coords.length,lon=coords.reduce((a,p)=>a+p[1],0)/coords.length;place={name:sd,lat:+lat.toFixed(3),lon:+lon.toFixed(3),tz:9,kr:true,sidoOnly:true};showPlace();if(!$("mapbox").hidden)drawMap()});
$("sgg").addEventListener("change",e=>{const v=e.target.value;if(!v)return;const [k,i]=v.split(":");choosePlace({k,i:+i})});
let pHits=[],pAct=-1;
function renderHits(){const ul=$("placeList");if(!pHits.length){ul.hidden=true;$("placeQ").setAttribute("aria-expanded","false");return}
  ul.innerHTML=pHits.map((h,j)=>`<li role="option" id="ph${j}" aria-selected="${j===pAct}" data-j="${j}"><b>${h.label}</b><small>${h.sub}</small></li>`).join("");ul.hidden=false;$("placeQ").setAttribute("aria-expanded","true")}
$("placeQ").addEventListener("input",e=>{const q=norm2(e.target.value);pAct=-1;if(!q){pHits=[];renderHits();return}
  const sc=o=>o.key.startsWith(q)?0:o.label.replace(/\s/g,"").includes(q)?1:o.key.includes(q)?2:9;
  pHits=PIDX.map(o=>[sc(o),o]).filter(x=>x[0]<9).sort((a,b)=>a[0]-b[0]||a[1].label.length-b[1].label.length).slice(0,8).map(x=>x[1]);renderHits()});
$("placeQ").addEventListener("keydown",e=>{if(!pHits.length)return;if(e.key==="ArrowDown"){pAct=(pAct+1)%pHits.length;renderHits();e.preventDefault()}
  else if(e.key==="ArrowUp"){pAct=(pAct-1+pHits.length)%pHits.length;renderHits();e.preventDefault()}
  else if(e.key==="Enter"){e.preventDefault();pick(pAct<0?0:pAct)}else if(e.key==="Escape"){pHits=[];renderHits()}});
function pick(j){const h=pHits[j];if(!h)return;choosePlace(h);$("placeQ").value="";pHits=[];renderHits()}
$("placeList").addEventListener("mousedown",e=>{const li=e.target.closest("li");if(li){e.preventDefault();pick(+li.dataset.j)}});
$("placeQ").addEventListener("blur",()=>setTimeout(()=>{pHits=[];renderHits()},120));
