const RR_I=["g","kk","n","d","tt","r","m","b","pp","s","ss","","j","jj","ch","k","t","p","h"],RR_V=["a","ae","ya","yae","eo","e","yeo","ye","o","wa","wae","oe","yo","u","wo","we","wi","yu","eu","ui","i"],RR_F=["","k","k","k","n","n","n","t","l","k","m","l","l","l","p","l","m","p","p","t","t","ng","t","t","k","t","p","t"];
const SURN2={"남궁":"Namgung","제갈":"Jegal","황보":"Hwangbo","선우":"Sunwoo","독고":"Dokgo","사공":"Sagong","서문":"Seomun"};
const SURN=Object.fromEntries("김Kim 이Lee 박Park 최Choi 정Jung 강Kang 조Cho 윤Yoon 장Jang 임Lim 한Han 오Oh 서Seo 신Shin 권Kwon 황Hwang 안Ahn 송Song 류Ryu 유Yoo 홍Hong 전Jeon 고Ko 문Moon 양Yang 손Son 배Bae 백Baek 허Heo 남Nam 심Shim 노Noh 하Ha 곽Kwak 성Sung 차Cha 주Joo 우Woo 구Koo 민Min 진Jin 나Na 엄Eom 채Chae 원Won 천Cheon 방Bang 공Kong 현Hyun 함Ham 변Byun 염Yeom 여Yeo 추Choo 도Do 소So 석Seok 선Sun 설Seol 마Ma 길Gil 연Yeon 위Wi 표Pyo 명Myung 기Ki 반Ban 왕Wang 금Keum 옥Ok 육Yook 인In 맹Maeng 제Je 모Mo 탁Tak 국Kook 어Eo 은Eun 편Pyeon 용Yong 예Ye 경Kyung 봉Bong 사Sa 부Boo 가Ka 복Bok 태Tae 목Mok 형Hyung 피Pi 두Doo 감Kam 호Ho 동Dong 온On 좌Jwa 상Sang".split(" ").map(t=>[t[0],t.slice(1)]));
function rrWord(w){let o="",pf=-1;for(const c of w){const k=c.charCodeAt(0)-0xAC00;if(k<0||k>11171){o+=c;pf=-1;continue}
  const i=Math.floor(k/588),v=Math.floor(k%588/28),f=k%28;let ini=RR_I[i];if(i===5&&pf===8)ini="l";o+=ini+RR_V[v]+RR_F[f];pf=f}return o}
function romanize(name){const n=(name||"").replace(/\s+/g,"");if(!/^[가-힣]{2,}$/.test(n))return "";
  const cap=t=>t?t[0].toUpperCase()+t.slice(1):"";
  let sur,given;if(n.length>=4&&SURN2[n.slice(0,2)]){sur=SURN2[n.slice(0,2)];given=n.slice(2)}else{sur=SURN[n[0]]||cap(rrWord(n[0]));given=n.slice(1)}
  return `${sur} ${cap(rrWord(given))}`}
