function romanNote(){const v=$("in-roman").value,l=v.toLowerCase().replace(/[^a-z]/g,"");
  $("romanNote").innerHTML=(l?`계산 글자 <b>${l.toUpperCase()}</b><br>`:"한글 이름을 쓰면 자동으로 채워져요<br>")+"사용하는 영문 이름을 입력해 주세요. 띄어쓰기·순서·대소문자는 상관없어요."}
