function spouseFaceHash(value){let h=2166136261;for(const c of value){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function spouseFaceProfile(ch){
 const gender=ch.male?'female':'male',mateElement=SE[BMAIN[ch.brs.d]];
 // Proprietary visual classification. These are artistic choices, not inferred physical facts.
 const family=(mateElement+(sign(ch.sun)%4)*2+ch.nk%3)%8;
 const key=['face-bank-v2',ch.Y,ch.Mo,ch.D,ch.stems.d,ch.brs.d,ch.stems.h??'?',ch.brs.h??'?',ch.cnt.join(','),ch.sun.toFixed(5),ch.asc==null?'?':ch.asc.toFixed(5),ch.nk,ch.lp,ch.msign,ch.tone].join('|');
 const candidates=SPOUSE_FACE_BANK.filter(p=>p.gender===gender&&p.family===family);
 if(candidates.length!==8)throw new Error('Incomplete spouse illustration family');
 return candidates[spouseFaceHash(key)%candidates.length];
}

function spousePreviewHTML(ch,topic='marry'){if(ch.inp.relationship==='married')return '';const face=spouseFaceProfile(ch),person=topic==='love'?'연애 상대':'배우자',E=topicEsc;return '<section class="spouse-preview" data-face-id="'+face.id+'" aria-labelledby="spouse-preview-title-'+topic+'"><header><h4 id="spouse-preview-title-'+topic+'">'+(topic==='love'?'인연일 가능성이 높은 사람':'배우자가 될 가능성이 높은 사람')+'</h4></header><div class="spouse-preview-content"><figure><div class="spouse-portrait"><img loading="lazy" decoding="async" src="'+face.preview+'" width="120" height="150" alt="흐리게 처리한 '+person+'의 상징 이미지" decoding="async"><div class="spouse-portrait-label"><span>선명한 모습은 리포트에서</span></div></div><figcaption class="spouse-preview-note">얼굴은 실제 인물 예측이 아닌 상징 이미지예요.</figcaption></figure><div class="spouse-preview-copy"><div class="spouse-face-traits">'+face.features.map(t=>'<span>'+E(t)+'</span>').join('')+'</div>'+(()=>{const pp=partnerProfile(ch);return '<dl class="spouse-facts"><div><dt>예상 MBTI</dt><dd>'+pp.mbti+'</dd></div><div><dt>예상 나이 차이</dt><dd>'+E(compactPartnerAge(pp.age))+'</dd></div></dl>'})()+'<button type="button" data-spouse-report>상세 리포트 보기 ↓</button></div></div></section>'}

document.addEventListener('click',e=>{const b=e.target.closest('[data-spouse-report]');if(!b)return;const section=b.closest('.spouse-preview');section?.parentElement.querySelector('.topic-offer')?.scrollIntoView({behavior:reduceM?'auto':'smooth',block:'center'})});
