const FENG_SITUATION_PICKS=[
 {label:'중요한 결정을 할 때',names:['서울대학교 관악캠퍼스','시그니엘 서울 더 라운지','포시즌스 호텔 서울 마루','서울신라호텔 더 라이브러리','파크 하얏트 부산 라운지']},
 {label:'답답할 때',names:['서울숲','남산 하늘숲길','하늘공원','북악산','여의도한강공원']},
 {label:'잘 안 풀릴 때',names:['서울식물원','동대문디자인플라자 DDP','국립현대미술관 덕수궁','관악산','아르떼뮤지엄 강릉']}
];
function fengSituationRecommendations(st){return '<div class="feng-situation-recommendations">'+FENG_SITUATION_PICKS.map(item=>{const p=FENG_PLACES.find(p=>p.name===item.names[+st.support]);return p?'<div><span>'+item.label+':</span> <button type="button" class="feng-inline-place" data-feng-pick="'+p.id+'" aria-pressed="'+(st.selected===p.id)+'">'+fengEscape(p.name)+'</button></div>':''}).join('')+'</div>'}
function fengPlaceCard(place){return '<article class="feng-place"><small>'+place.region+' · '+ELK[place.e]+'('+EL[place.e]+')</small><h4>'+place.name+'</h4><p>'+place.action+'</p></article>'}

const FENG_REGIONS=['서울','인천','경기','강원','충북','충남','대전','세종','전북','전남','광주','경북','경남','대구','울산','부산','제주'];
const fengEscape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));


function fengFilter(st){const order=String(st.order||st.support+',0,1,2,3,4').split(',').map(Number);const category=st.category==null||st.category===''?+st.support:+st.category;return FENG_PLACES.filter(p=>p.e===category).sort((a,b)=>order.indexOf(a.e)-order.indexOf(b.e)||FENG_PLACES.indexOf(a)-FENG_PLACES.indexOf(b))}
function fengXY(p){return [(p.lon-MAPS.kv[2])*MAPS.kv[4]*MAPS.kv[5],(MAPS.kv[3]-p.lat)*MAPS.kv[4]]}
function fengClampView(v){const [W,H]=MAPS.kv,w=clamp(v[2],W/48,W),h=w*H/W;return [clamp(v[0],-W*.15,W*1.15-w),clamp(v[1],-H*.15,H*1.15-h),w,h]}
function fengView(st){const [W,H]=MAPS.kv;return Number.isFinite(+st.vx)&&st.vx!==''&&+st.vw>0?fengClampView([+st.vx,+st.vy,+st.vw,+st.vh]):[0,0,W,H]}
function fengZoomView(v,factor,anchor,origin=anchor){const [W,H]=MAPS.kv,w=clamp(v[2]/factor,W/48,W),h=w*H/W;return fengClampView([v[0]+origin[0]*v[2]-anchor[0]*w,v[1]+origin[1]*v[3]-anchor[1]*h,w,h])}
function fengFocusedView(st,p){const v=fengView(st),[x,y]=fengXY(p),pad=.12;if(x>=v[0]+v[2]*pad&&x<=v[0]+v[2]*(1-pad)&&y>=v[1]+v[3]*pad&&y<=v[1]+v[3]*(1-pad))return v;return fengClampView([x-v[2]/2,y-v[3]/2,v[2],v[3]])}
function fengMarkerSize(v,width,active){const scale=v[2]/Math.max(width,240);return {r:(active?4.5:3.5)*scale,halo:0,hit:12*scale}}
function fengMarkerPath(x,y,r){return 'M'+(x-r)+','+y+'a'+r+','+r+' 0 1,0 '+(2*r)+',0a'+r+','+r+' 0 1,0 '+(-2*r)+',0'}
function fengLinks(p){const q=encodeURIComponent(p.name+' '+p.region);return '<div class="feng-directions" aria-label="위치와 길찾기">'+[['네이버맵','https://map.naver.com/p/search/'+q],['카카오맵','https://map.kakao.com/link/search/'+q],['구글맵','https://www.google.com/maps/search/?api=1&query='+q]].map(([n,url])=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+n+' ↗</a>').join('')+'</div>'}

function fengExplorerBody(st){if(st.compact==='1')return fengCompactBody(st);const rows=fengFilter(st),chosen=rows.find(p=>p.id===st.selected)||rows[0],v=fengView(st),recommended=FENG_PLACES.filter(p=>p.e===+st.support).slice(0,3),recommendedIds=new Set(recommended.map(p=>p.id));
 const placeButton=(p,compact)=>'<button type="button" class="'+(compact?'feng-inline-place':'feng-region-place')+'" data-feng-pick="'+p.id+'" aria-pressed="'+(p===chosen)+'">'+fengEscape(p.name)+(compact?'':'<small>'+fengEscape(p.region)+'</small>')+'</button>';
 const intro='<div class="feng-recommend-line"><strong>나에게 추천하는 장소:</strong> '+recommended.map(p=>placeButton(p,true)).join('<span aria-hidden="true"> · </span>')+'</div>';

 const available=FENG_REGIONS.filter(region=>rows.some(p=>p.province===region)),region=available.includes(st.region)?st.region:'',list=rows.filter(p=>(!region||p.province===region)&&(region||!recommendedIds.has(p.id))),limit=Math.max(6,+st.limit||6),visible=list.slice(0,limit);
 const groups='<div class="feng-browse"><div class="feng-browse-head"><h4>장소 둘러보기</h4><label><span class="sr-only">지역 선택</span><select data-feng-region aria-label="방문할 지역"><option value="">전국</option>'+available.map(r=>'<option value="'+r+'"'+(r===region?' selected':'')+'>'+r+'</option>').join('')+'</select></label></div><div class="feng-compact-list">'+visible.map(p=>'<button type="button" data-feng-pick="'+p.id+'" aria-pressed="'+(p===chosen)+'"><span>'+fengEscape(p.name)+'</span><small>'+fengEscape(p.region)+'</small><span class="feng-list-arrow" aria-hidden="true">›</span></button>').join('')+'</div>'+(list.length>limit?'<button type="button" class="feng-more" data-feng-more>더 보기</button>':'')+'</div>';
 const map='<div class="feng-map-wrap"><svg class="feng-map" viewBox="'+v.join(' ')+'" tabindex="0" role="group" aria-label="전국 장소 지도. 확대하면 지역명이 표시됩니다."><g class="feng-land">'+MAPS.kor.map(r=>'<path d="'+r[2]+'"/>').join('')+'</g><g class="feng-geo-labels" aria-hidden="true"></g>'+[...rows.filter(p=>p!==chosen),chosen].filter(Boolean).map(p=>{const [x,y]=fengXY(p),active=p===chosen,size=fengMarkerSize(v,380,active);return '<g class="feng-pin'+(active?' active':'')+'" role="button" tabindex="0" data-feng-pick="'+p.id+'" aria-label="'+fengEscape(p.name+' · '+p.region)+'" aria-pressed="'+active+'"><title>'+fengEscape(p.name+' · '+p.region)+'</title><path class="feng-hit" d="'+fengMarkerPath(x,y,size.hit)+'" fill="transparent"/><path class="feng-dot" d="'+fengMarkerPath(x,y,size.r)+'" style="fill:var(--el'+p.e+');stroke:none;stroke-width:0;filter:none"/></g>'}).join('')+'</svg><button type="button" class="feng-overview" data-feng-overview>전국 보기</button></div>';
 const active=st.category==null||st.category===''?+st.support:+st.category;
 const categories='<div class="feng-categories" role="group" aria-label="지도에 표시할 장소 카테고리">'+ELK.map((name,e)=>'<button type="button" data-feng-category="'+e+'" class="'+(e===+st.support?'recommended':'')+'" aria-pressed="'+(e===active)+'" style="--category-color:var(--el'+e+')"><span><i aria-hidden="true"></i>'+name+'</span><em>'+ACTION_ELEMENTS[e].theme+'</em>'+(e===+st.support?'<small>나에게 추천</small>':'')+'</button>').join('')+'</div>';
 return intro+fengSituationRecommendations(st)+categories+'<div class="feng-map-layout">'+map+'<div class="feng-selected" aria-live="polite">'+(chosen?fengPlaceCard(chosen)+fengLinks(chosen):'')+'</div></div>'+groups;
}



function fengCompactPlacesHTML(ch){const support=actionProfile(ch).support,related=[...new Set([support,...ch.goodG.map(g=>(SE[ch.stems.d]+g)%5)])];const st={compact:'1',support:String(support),related:related.join(','),selected:''};return '<div class="feng-explorer compact-places" '+Object.entries(st).map(([k,v])=>'data-'+k+'="'+v+'"').join(' ')+'>'+fengCompactBody(st)+'</div>'}


const fengObserver=typeof ResizeObserver==='function'?new ResizeObserver(entries=>entries.forEach(({target})=>{const el=target.closest('.feng-explorer');if(el)fengPaint(el)})):null;

const FENG_PROVINCE_LABELS=SIDO.map(name=>{const pts=MAPS.kor.map((r,i)=>r[1]===name?KC[i]:null).filter(Boolean);return {name,lat:pts.reduce((n,p)=>n+p[0],0)/pts.length,lon:pts.reduce((n,p)=>n+p[1],0)/pts.length}});
function fengGeoLabels(st,v,width){const z=MAPS.kv[0]/v[2],unit=v[2]/Math.max(width,1),height=width*MAPS.kv[1]/MAPS.kv[0],boxes=[],labels=[];
 const put=(name,pos,kind,offset=0)=>{const sx=(pos[0]-v[0])/unit,sy=(pos[1]-v[1])/unit+offset,font=kind==='province'?13:kind==='selected'?12:11,tw=name.length*font*.88+12,box=[sx-tw/2,sy-font-4,tw,font+8];if(box[0]<2||box[0]+box[2]>width-2||box[1]<2||box[1]+box[3]>height-2)return;if(boxes.some(b=>box[0]<b[0]+b[2]&&box[0]+box[2]>b[0]&&box[1]<b[1]+b[3]&&box[1]+box[3]>b[1]))return;boxes.push(box);labels.push('<text class="feng-label '+kind+'" x="'+pos[0]+'" y="'+(pos[1]+offset*unit)+'" text-anchor="middle" font-size="'+font*unit+'" stroke-width="'+3*unit+'">'+fengEscape(name)+'</text>')};
 const visible=fengFilter(st),chosen=visible.find(p=>p.id===st.selected)||visible[0];if(chosen)put(chosen.name,fengXY(chosen),'selected',-14);
 FENG_PROVINCE_LABELS.forEach(p=>put(p.name,fengXY(p),'province'));
 if(z>=2.5)MAPS.kor.forEach((r,i)=>put(kname(r[0]),fengXY({lat:KC[i][0],lon:KC[i][1]}),'city'));
 if(z>=7)visible.filter(p=>p!==chosen).forEach(p=>put(p.name,fengXY(p),'place',-12));
 return labels.join('');
}

function fengPaint(el){const svg=el.querySelector('.feng-map');if(!svg)return;const v=fengView(el.dataset),width=svg.getBoundingClientRect().width||380;svg.setAttribute('viewBox',v.join(' '));const geo=svg.querySelector('.feng-geo-labels');if(geo)geo.innerHTML=fengGeoLabels(el.dataset,v,width);svg.querySelectorAll('.feng-pin').forEach(pin=>{const size=fengMarkerSize(v,width,pin.classList.contains('active'));const p=FENG_PLACES.find(p=>p.id===pin.dataset.fengPick);if(!p)return;const [x,y]=fengXY(p);pin.querySelector('.feng-hit').setAttribute('d',fengMarkerPath(x,y,size.hit));pin.querySelector('.feng-dot').setAttribute('d',fengMarkerPath(x,y,size.r))})}
function fengSetView(el,v){const c=fengClampView(v);Object.assign(el.dataset,{vx:String(c[0]),vy:String(c[1]),vw:String(c[2]),vh:String(c[3])});fengPaint(el)}
function fengInit(root){root.querySelectorAll('.feng-map').forEach(svg=>{fengObserver?.observe(svg);fengPaint(svg.closest('.feng-explorer'))})}
function fengRefresh(el,changes){const old=el.querySelector('.feng-map');if(old)fengObserver?.unobserve(old);Object.assign(el.dataset,changes);el.innerHTML=fengExplorerBody(el.dataset);fengInit(el)}
function fengSelect(el,id,center){if(el.dataset.compact==='1'){const pl=FENG_PLACES.find(p=>p.id===id);const sc=el.querySelector('.cp-scroll')?.scrollTop||0;if(pl){const [x,y]=fengXY(pl);el.dataset.cx=String(x);el.dataset.cy=String(y)}fengRefresh(el,{selected:id});cpApply(el);const sb=el.querySelector('.cp-scroll');if(sb)sb.scrollTop=sc;const list=el.querySelector('.cp-list');if(list){list.scrollLeft=top;list.querySelector('[aria-pressed=true]')?.scrollIntoView({block:'nearest',inline:'nearest'})}return}const p=FENG_PLACES.find(p=>p.id===id);if(!p)return;let changes={selected:id,category:String(p.e)};if(center){const v=fengFocusedView(el.dataset,p);Object.assign(changes,{vx:String(v[0]),vy:String(v[1]),vw:String(v[2]),vh:String(v[3])})}fengRefresh(el,changes)}
let fengSuppressClickUntil=0;
function fengClick(e){const ctl=e.target.closest('[data-feng-pick],[data-feng-map],[data-feng-category],[data-feng-more],[data-feng-overview]'),el=ctl&&ctl.closest('.feng-explorer');if(!el)return;if(e.type==='keydown'){if(e.key!=='Enter'&&e.key!==' ')return;e.preventDefault()}if(e.type==='click'&&ctl.closest('.feng-map')&&Date.now()<fengSuppressClickUntil)return;
 if(ctl.hasAttribute('data-feng-overview')){fengSetView(el,[0,0,MAPS.kv[0],MAPS.kv[1]]);return}
 if(ctl.hasAttribute('data-feng-more')){fengRefresh(el,{limit:String((+el.dataset.limit||6)+6)});return}
 if(ctl.dataset.fengCategory!=null){const category=ctl.dataset.fengCategory;fengRefresh(el,{category,region:'',limit:'6',selected:'',vx:'0',vy:'0',vw:String(MAPS.kv[0]),vh:String(MAPS.kv[1])});el.querySelector('[data-feng-category="'+category+'"]')?.focus({preventScroll:true});return}
 if(ctl.dataset.fengPick)fengSelect(el,ctl.dataset.fengPick,!ctl.closest('.feng-map'));else{let v=fengView(el.dataset),cmd=ctl.dataset.fengMap;if(cmd==='in')v=fengZoomView(v,1.5,[.5,.5]);if(cmd==='out')v=fengZoomView(v,1/1.5,[.5,.5]);if(cmd==='left')v[0]-=v[2]*.22;if(cmd==='right')v[0]+=v[2]*.22;if(cmd==='up')v[1]-=v[3]*.22;if(cmd==='down')v[1]+=v[3]*.22;if(cmd==='reset')v=[0,0,MAPS.kv[0],MAPS.kv[1]];fengSetView(el,v)}
 if(e.type==='keydown'||!ctl.closest('.feng-map'))el.querySelector((ctl.closest('.feng-map')?'.feng-pin':'')+'[data-feng-pick="'+el.dataset.selected+'"]')?.focus({preventScroll:true});
}
document.addEventListener('keydown',e=>{if(!e.target.matches('.feng-map'))return;const el=e.target.closest('.feng-explorer');let v=fengView(el.dataset),key=e.key;if(key==='+'||key==='=')v=fengZoomView(v,1.5,[.5,.5]);else if(key==='-')v=fengZoomView(v,1/1.5,[.5,.5]);else if(key==='ArrowLeft')v[0]-=v[2]*.2;else if(key==='ArrowRight')v[0]+=v[2]*.2;else if(key==='ArrowUp')v[1]-=v[3]*.2;else if(key==='ArrowDown')v[1]+=v[3]*.2;else if(key==='Home')v=[0,0,MAPS.kv[0],MAPS.kv[1]];else return;e.preventDefault();fengSetView(el,v)});
document.addEventListener('change',e=>{const ctl=e.target.closest('[data-feng-region]'),el=ctl&&ctl.closest('.feng-explorer');if(!el)return;fengRefresh(el,{region:ctl.value,limit:'6'});el.querySelector('[data-feng-region]')?.focus({preventScroll:true})});
document.addEventListener('click',e=>{const b=e.target.closest('[data-cp-zoom]');if(!b)return;const el=b.closest('.feng-explorer');if(!el)return;const a=b.dataset.cpZoom;if(a==='all'){el.dataset.z='1';cpApply(el)}else cpZoomAt(el,a==='in'?2:.5,+el.dataset.cx,+el.dataset.cy)});
document.addEventListener('toggle',e=>{const d=e.target;if(d.matches&&d.matches('.cp-more')){const el=d.closest('.feng-explorer');if(el)el.dataset.more=d.open?'1':''}},true);
document.addEventListener('click',fengClick);document.addEventListener('keydown',e=>{if(e.target.matches('.feng-pin'))fengClick(e)});
document.addEventListener('wheel',e=>{const svg=e.target.closest('.feng-map');if(!svg)return;e.preventDefault();const el=svg.closest('.feng-explorer'),r=svg.getBoundingClientRect(),unit=e.deltaMode===1?16:e.deltaMode===2?r.height:1,anchor=[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height];fengSetView(el,fengZoomView(fengView(el.dataset),Math.exp(-clamp(e.deltaY*unit,-400,400)*.002),anchor))},{passive:false});
const fengGestures=new WeakMap();
function fengGestureStart(g,el){g.base=fengView(el.dataset);const pts=[...g.points.values()];g.start=pts.map(p=>({...p}));}
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('.feng-map');if(!svg||e.pointerType==='mouse'&&e.button!==0)return;const el=svg.closest('.feng-explorer');let g=fengGestures.get(svg);if(!g){g={points:new Map(),moved:false,pick:null};fengGestures.set(svg,g)}if(!g.points.size){g.moved=false;g.pick=e.target.closest('[data-feng-pick]')?.dataset.fengPick||null}g.points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(g.points.size>1){g.moved=true;g.pick=null}fengGestureStart(g,el);svg.setPointerCapture(e.pointerId);svg.classList.add('dragging')});
document.addEventListener('pointermove',e=>{const svg=e.target.closest('.feng-map'),g=svg&&fengGestures.get(svg);if(!g?.points.has(e.pointerId))return;g.points.set(e.pointerId,{x:e.clientX,y:e.clientY});const el=svg.closest('.feng-explorer'),r=svg.getBoundingClientRect(),pts=[...g.points.values()],start=g.start;if(!r.width||!r.height)return;
 if(pts.length===1){const dx=pts[0].x-start[0].x,dy=pts[0].y-start[0].y;if(Math.hypot(dx,dy)>4)g.moved=true;fengSetView(el,[g.base[0]-dx/r.width*g.base[2],g.base[1]-dy/r.height*g.base[3],g.base[2],g.base[3]])}
 else{const mid=arr=>[(arr[0].x+arr[1].x)/2,(arr[0].y+arr[1].y)/2],from=mid(start),to=mid(pts),dist=arr=>Math.hypot(arr[0].x-arr[1].x,arr[0].y-arr[1].y),factor=dist(pts)/Math.max(1,dist(start));fengSetView(el,fengZoomView(g.base,factor,[(to[0]-r.left)/r.width,(to[1]-r.top)/r.height],[(from[0]-r.left)/r.width,(from[1]-r.top)/r.height]))}
});
function fengPointerEnd(e){const svg=e.target.closest('.feng-map'),g=svg&&fengGestures.get(svg);if(!g?.points.has(e.pointerId))return;const el=svg.closest('.feng-explorer');g.points.delete(e.pointerId);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);fengSuppressClickUntil=Date.now()+500;if(g.points.size){fengGestureStart(g,el);return}svg.classList.remove('dragging');if(e.type==='pointerup'&&!g.moved&&g.pick)fengSelect(el,g.pick,false);fengGestures.delete(svg)}
document.addEventListener('pointerup',fengPointerEnd);document.addEventListener('pointercancel',fengPointerEnd);
document.addEventListener('toggle',e=>{if(e.target.open&&e.target.querySelector('.feng-map'))requestAnimationFrame(()=>fengInit(e.target))},true);

function actionProfile(ch){
 const dominant=ch.cnt.indexOf(Math.max(...ch.cnt));
 const candidates=[...new Set(ch.goodG.map(g=>(SE[ch.stems.d]+g)%5))];
 candidates.sort((a,b)=>ch.cnt[a]-ch.cnt[b]||a-b);
 const support=candidates[0];
 return {dominant,support,strong:ACTION_ELEMENTS[dominant],fill:ACTION_ELEMENTS[support]};
}
