let accountToken=lsGet('oracle-session')||'',accountUser=null,accountBusy=false,formVersion=0,accountChecking=!!accountToken;
const accountStatus=text=>{$('accountStatus').textContent=text};
function accountNotice(text){accountStatus(text);$('authFeedbackText').textContent=text;$('authFeedback').hidden=!text}
$('authFeedbackClose').addEventListener('click',()=>{$('authFeedback').hidden=true});
// In-app browsers can return in a new tab: keep the proof for at most ten minutes.
function clearLoginProof(){for(const storage of ['sessionStorage','localStorage'])try{window[storage].removeItem('oracle-verifier');window[storage].removeItem('oracle-login-proof')}catch(_){}}
function saveLoginProof(verifier){
 let saved=false;const proof=JSON.stringify({verifier,expires:Date.now()+600000});
 for(const storage of ['sessionStorage','localStorage'])try{window[storage].setItem('oracle-login-proof',proof);saved=true}catch(_){}
 if(!saved)throw new Error('브라우저의 사이트 저장 공간을 허용한 뒤 다시 로그인해 주세요.');
}
function readLoginProof(){
 for(const storage of ['sessionStorage','localStorage'])try{
  const p=JSON.parse(window[storage].getItem('oracle-login-proof')||'null');
  if(p&&p.expires>Date.now()&&/^[a-f0-9]{64}$/.test(p.verifier))return p.verifier;
 }catch(_){}
 clearLoginProof();return null;
}
function accountPaint(){
  /* 새로고침 직후 토큰이 있으면 서버 확인 전에도 로그인 상태로 그린다(로그아웃 깜빡임 방지). */
  const member=!!accountUser||(!!accountToken&&accountChecking),nick=accountUser?accountUser.nickname:lsGet('oracle-nick');
  $('accountLogin').hidden=member;$('accountMember').hidden=!member;
  paintAccessAccount();$('accountHello').textContent=member?(nick||'회원')+'님':'';
  $('saveGuest').hidden=member;$('saveMember').hidden=!member;
  $('profileLoad').disabled=!accountUser?.profile||accountBusy;$('profileDelete').disabled=!accountUser?.profile||accountBusy;
  $('profileSave').disabled=accountBusy;$('accountLogout').disabled=accountBusy;
}
async function accountAPI(path,body){
  const headers={};if(accountToken)headers.Authorization='Bearer '+accountToken;if(body!==undefined)headers['Content-Type']='application/json';
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);
  let r;try{r=await fetch(INVITE_API+path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:controller.signal})}finally{clearTimeout(timeout)}
  let data={};try{data=await r.json()}catch(_){if(r.ok)throw new TypeError('bad_json')}if(!r.ok&&path==='/partners'&&r.status!==401){throw new Error(data.error==='partner_limit'?'저장 가능한 상대는 최대 20명이에요. 기존 정보를 삭제한 뒤 다시 저장해 주세요.':data.error==='invalid_partner'?'상대방의 이름·영문 이름·출생 정보를 확인해 주세요.':r.status===404?'상대 정보 저장 서버의 경로가 연결되지 않았어요. 서버 업데이트가 필요해요.':'상대 정보 저장 서버에 연결하지 못했어요. 잠시 뒤 다시 시도해 주세요.')}if(!r.ok){if(r.status===401){accountToken='';accountUser=null;accountChecking=false;try{localStorage.removeItem('oracle-session');localStorage.removeItem('oracle-nick')}catch(_){}accountPaint()}throw new Error(r.status===401?'로그인이 만료됐어요. 다시 로그인해 주세요.':r.status===403?'리포트 열람 승인이 필요해요. 관리자에게 계정 ID와 원하는 리포트를 알려주세요.':r.status===409?(data.error==='profile_conflict'?'다른 화면에서 정보가 변경됐어요. 새로고침 후 다시 확인해 주세요.':'저장된 출생 정보가 필요해요. 내 정보에서 출생 정보를 저장해주세요.'):r.status===404?'리포트 또는 권한 서버를 준비하고 있어요.':r.status===503?'카카오 로그인 설정을 마무리하고 있어요.':r.status===429?'요청이 많아요. 잠시 뒤 다시 시도해 주세요.':'요청을 처리하지 못했어요. 잠시 뒤 다시 시도해 주세요.')}
  /* 관리자 테스트 모드(admin-test.js): 진짜 관리자 여부는 따로 기억하고, '일반 회원처럼 보기'가 켜져 있으면 화면에는 관리자가 아닌 것으로 알린다(서버 권한은 그대로). */
  if(path==='/me'&&data)lsSet('oracle-real-admin',data.isAdmin?'1':'0');if(data&&data.isAdmin&&lsGet('oracle-test-member')==='1')data.isAdmin=false;
  return data;
}
function profileFill(v){
  const p=JSON.parse(JSON.stringify(v));if(p.place?.ki!=null&&p.place.ki>=MAPS.kor.length)delete p.place.ki;if(p.place?.wi!=null&&p.place.wi>=MAPS.world.length)delete p.place.wi;if(p.place?.ci!=null&&p.place.ci>=PLACES.length)delete p.place.ci;
  fillForm(p);formVersion++;$('askbox').open=true;$('err').textContent='';
}
